package com.godrayine.kanastudio;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.Base64;
import java.util.HashSet;

/** Golden cases generated by the Windows converter: verifies cross-platform parity. */
public final class EngineTest {
    private static String decode(String value) {
        return new String(Base64.getDecoder().decode(value), StandardCharsets.UTF_8);
    }
    public static void main(String[] args) throws Exception {
        int count = 0;
        for (String line : Files.readAllLines(Paths.get(args[0]), StandardCharsets.UTF_8)) {
            String[] fields = line.split("\t", -1);
            KanaEngine.Options options = new KanaEngine.Options();
            options.alphabet = fields[1]; options.density = Integer.parseInt(fields[2]);
            options.snowball = fields[3].equals("1"); options.replaceE = fields[4].equals("1");
            options.wideSpaces = fields[5].equals("1");
            options.selected = new HashSet<>();
            if (!fields[6].isEmpty()) options.selected.addAll(Arrays.asList(decode(fields[6]).split(",")));
            KanaEngine.Result result = KanaEngine.convert(decode(fields[0]), options);
            StringBuilder segments = new StringBuilder();
            for (KanaEngine.Segment segment : result.segments) segments.append(segment.text).append('\u0001').append(segment.original).append('\u0001').append(segment.reading).append('\u0002');
            if (!result.text.equals(decode(fields[7])) || result.replacements != Integer.parseInt(fields[8]) || result.possible != Integer.parseInt(fields[9]) || result.unique != Integer.parseInt(fields[10]) || !segments.toString().equals(decode(fields[11])))
                throw new AssertionError("Desktop parity failed at case " + (count + 1));
            count++;
        }
        if (KanaEngine.baseReadings().size() != 46 || KanaTable.ALL.length != 104) throw new AssertionError("Kana table size");
        System.out.println("PASS: " + count + " desktop parity cases (output, counts, segments); 104 kana, 46 basic.");
    }
}
